OA23 = "LE07 OA 23"
MAT_O = "Este cuaderno, lápiz y los guiones escritos en cada ejercicio. Para la tarea abierta, una persona de tu casa que te escuche."

L(OA23, 1,
  MAT_O,
  "Aprenderé a comparar un texto oral con uno escrito sobre el mismo mensaje y a explicar sus diferencias según el contexto y el destinatario.",
  ["Distingo propósito y audiencia.", "Reconozco muletillas."],
  ["Un mismo mensaje puede decirse de forma oral o escrita, y cada forma tiene rasgos propios. El texto oral se produce en el momento, con la voz, el tono, los gestos y la mirada. Suele tener repeticiones, pausas, muletillas («eeh», «o sea») y expresiones que llaman al otro («¿ya?», «¿cachai?»). Su ventaja es que se puede ajustar sobre la marcha según la reacción de quien escucha.",
   "El texto escrito se planifica y se revisa antes de entregarse. Usa puntuación para marcar las pausas, es más preciso (dice «a las 16:00» y no «como a las cuatro») y puede releerse. No cuenta con gestos ni tono, así que debe incluir todo lo necesario en las palabras.",
   "Para compararlos, fíjate en cuatro rasgos: planificación, precisión, recursos que usa (voz o puntuación) y posibilidad de corregir. El contexto y el destinatario deciden cuál conviene: un aviso que queda en el muro necesita ser escrito; una conversación para ponerse de acuerdo con un amigo suele ser oral. Cambiar de uno a otro exige adaptar el mensaje, no solo copiarlo."],
  [("texto oral", "mensaje que se comunica hablando, en el momento"), ("texto escrito", "mensaje que se comunica por escrito y puede releerse"), ("destinatario", "persona a quien va dirigido un mensaje"), ("contexto", "situación en la que se comunica algo")],
  [("Comparar dos versiones", "Oral: «Eeh, mira, el viernes, como a las cuatro, nos juntamos en la plaza, ¿ya?». Escrito: «Nos reuniremos el viernes a las 16:00 en la plaza». ¿Cuál es más precisa en la hora?",
    ["Comparo las horas.", "El oral dice «como a las cuatro».", "El escrito dice «a las 16:00»."],
    "El escrito"),
   ("Adaptar el mensaje", "Un aviso para el muro del colegio, ¿debe ser oral o escrito?",
    ["El aviso queda para que muchos lo lean.", "Debe poder releerse.", "Conviene escrito."],
    "Escrito")],
  [("Escribir como se habla.", "Se copian muletillas y expresiones de la conversación.", "Adapta el mensaje: sin muletillas y con datos precisos."),
   ("Pensar que lo oral es de peor calidad.", "Se compara sin considerar el contexto.", "Cada forma sirve para situaciones distintas.")],
  ([E("¿Qué texto puede releerse: el oral o el escrito?", "El escrito", "Queda fijado en papel o pantalla."),
    E("¿Cuál tiene muletillas como «eeh»: el oral o el escrito?", "El oral", "Surgen al hablar en el momento."),
    E("¿«¿Cachai?» es un llamado al interlocutor propio del texto oral o del escrito formal?", "Del texto oral", "Busca la reacción del oyente.")],
   [E("Oral: «Eeh, el viernes, como a las cuatro, nos juntamos». ¿Qué dato es impreciso: el día o la hora?", "La hora", "«Como a las cuatro» no es exacta."),
    E("Un cartel dice: «Reunión el viernes a las 16:00 en la plaza». ¿Está dirigido a un destinatario presente o a muchos que pasarán a leerlo?", "A muchos que pasarán a leerlo", "Es un aviso público."),
    E("¿Qué recurso del texto escrito marca las pausas: la puntuación o el tono?", "La puntuación", "El tono es propio de lo oral.")],
   [E("Cuenta las muletillas «eeh» y «o sea» en: «Eeh, el taller, o sea, empieza, eeh, mañana».", "3", "Hay dos «eeh» y un «o sea»."),
    E("Oral: «Nos vemos allá, ¿ya?». ¿Qué parte llama al otro para confirmar: «Nos vemos allá» o «¿ya?»?", "¿ya?", "Busca la respuesta del oyente."),
    E("Oral: «Mañana, mañana temprano, vamos al museo». ¿Qué palabra se repite al comienzo?", "Mañana", "El hablante la dice dos veces mientras piensa.")],
   [E("Ema escribe en un correo formal «Eeh, mire, necesito saber, o sea, si hay cupo». Rolando escribe «Necesito saber si hay cupo». ¿Quién adaptó el texto oral al escrito?", "Rolando", "Eliminó las muletillas del mensaje."),
    E("Un amigo te pregunta en el patio qué hora es. ¿Respondes de forma oral o escrita?", "Oral", "La situación es una conversación directa.")],
   [arith("Un mismo mensaje se dice oral en 15 palabras y escrito en 9. ¿Cuántas palabras menos tiene el escrito?", "15-9", "Se restan las palabras del escrito."),
    E("¿Cuál es mejor para un informe del colegio: texto oral o escrito?", "Escrito", "Se entrega y se lee con calma.")]),
  [E("Invitas a tu curso a una actividad. Por el chat de curso escribes «Nos vemos en el patio a las 10:00». ¿Es texto oral o escrito?", "Escrito", "Aunque sea breve, se comunica por escrito.")],
  [E("¿Qué rasgo es propio del texto oral: tono de voz o puntuación?", "Tono de voz", "Es un recurso de la voz."),
   E("¿Qué texto suele planificarse y revisarse: el escrito o el oral improvisado?", "El escrito", "Permite corregir antes de entregar."),
   E("¿Cómo se adapta un mensaje oral al escrito?", "Sin muletillas y con datos precisos", "Así se entiende por sí solo.")],
  ("Lee esta versión oral: «Eeh, hola, mira, o sea, mañana a las diez, como a las diez, nos juntamos a ensayar, ¿ya?, en la sala 3, ¿cachai?». 1) Cuenta cuántas veces aparecen «eeh», «o sea», «¿ya?» y «¿cachai?». 2) Escribe una versión escrita para el muro. 3) Escribe dos diferencias entre ambas.",
   "Aparecen 4 veces: eeh, o sea, ¿ya? y ¿cachai?. Versión escrita: «Ensayo mañana a las 10:00 en la sala 3». Diferencias: el oral tiene muletillas y hora aproximada; el escrito es preciso y breve.",
   ["identifica muletillas", "escribe una versión precisa y breve", "explica dos diferencias"], ["conteo", "versión escrita", "dos diferencias"], ["copiar las muletillas", "dejar «como a las diez»"], "Pide a otra persona que lea tu versión escrita y diga si le falta algún dato."),
  "Graba o recuerda un mensaje oral de tu día y escríbelo para un cartel.",
  "Escribe un mensaje de despedida oral y su versión escrita formal.")

L(OA23, 2,
  MAT_O,
  "Aprenderé a reconocer el contexto, el propósito y el destinatario de un texto oral y a usarlos para decidir qué decir y cómo decirlo.",
  ["Comparo texto oral y escrito.", "Distingo informar, pedir y agradecer."],
  ["Toda comunicación ocurre en una situación. El emisor es quien habla y el destinatario, quien escucha. El propósito es lo que se quiere lograr: informar, pedir, convencer, agradecer, entretener. El contexto incluye el lugar, el momento, la relación entre las personas y lo que ya saben. Estos elementos deciden qué se dice y cómo.",
   "Piensa en estos casos. Para pedir a la directora que autorice una actividad, hablas con cortesía, usas términos precisos y explicas tus razones. Para invitar a un amigo al cine, usas un tono relajado y frases cortas. El propósito es el mismo (pedir o invitar), pero cambian el destinatario y el contexto, y por eso cambia el mensaje.",
   "Un modo de decidir es responder cuatro preguntas antes de hablar: ¿quién me escucha?, ¿para qué hablo?, ¿dónde y cuándo?, ¿qué saben ya? Con esas respuestas eliges el vocabulario, el tono y el orden de las ideas. Una buena adecuación no cambia lo que piensas: cambia la forma en que lo comunicas."],
  [("emisor", "persona que dice el mensaje"), ("destinatario", "persona a quien va dirigido el mensaje"), ("propósito", "lo que se quiere lograr al comunicar"), ("adecuación", "ajuste del mensaje a la situación y al destinatario")],
  [("Identificar los elementos", "Una estudiante dice a la directora: «Con su permiso, quisiera solicitar la sala para ensayar». ¿Cuál es el destinatario y el propósito?",
    ["Habla a la directora.", "Quiere que le presten la sala.", "Destinatario: la directora; propósito: pedir."],
    "Destinatario: la directora; propósito: pedir"),
   ("Adecuar el mensaje", "Quieres invitar a un amigo al cine. ¿Qué frase es más adecuada: «Con su venia, ¿me concedería el honor de acompañarme?» o «¿Vamos al cine el sábado?»",
    ["Pienso en la relación: amigos.", "Un tono relajado es adecuado.", "Elijo la segunda."],
    "¿Vamos al cine el sábado?")],
  [("Hablar igual a todos los destinatarios.", "Se usa siempre el mismo tono.", "Piensa quién te escucha y para qué."),
   ("Cambiar tus ideas para agradar.", "Se confunde adecuarse con cambiar de opinión.", "Cambia la forma, no lo que piensas.")],
  ([E("¿Quién es el emisor: el que habla o el que escucha?", "El que habla", "Envía el mensaje."),
    E("En «Con su permiso, quisiera solicitar la sala», ¿cuál es el propósito: pedir o agradecer?", "Pedir", "Quiere que le presten la sala."),
    E("¿Qué es el destinatario?", "La persona a quien va dirigido el mensaje", "Es quien recibe lo dicho.")],
   [E("Quieres agradecer a una vecina que cuidó a tu perro. ¿Cuál es el propósito: agradecer o pedir?", "Agradecer", "Reconoces su ayuda."),
    E("Hablas con un amigo en el recreo. ¿Qué tono corresponde: relajado o muy solemne?", "Relajado", "El contexto es cercano."),
    E("Pides un favor al director. ¿Qué es más adecuado: «Buenos días, ¿podría ayudarme?» o «¡Oye, ayúdame!»", "Buenos días, ¿podría ayudarme?", "Es cortés y formal.")],
   [E("Antes de explicar los volcanes a niños de 1.º, ¿qué pregunta te ayuda a elegir el vocabulario: «¿quién me escucha?» o «¿cuántas láminas haré?»", "¿Quién me escucha?", "Define el nivel de las palabras."),
    E("Quieres explicar un tema a niños de 1.º. ¿Qué hay que adaptar: el vocabulario o tu opinión?", "El vocabulario", "La forma cambia con el destinatario."),
    E("Pides a un compañero su lápiz. ¿Qué es más adecuado: «¿Me prestas tu lápiz, por favor?» o «¡Dame el lápiz!»", "¿Me prestas tu lápiz, por favor?", "Es una petición cortés.")],
   [E("Ana pide permiso a la directora diciendo «Oye, deja usar la sala, ya». Beto dice «Con su permiso, ¿podría usar la sala para ensayar?». ¿Quién se adecuó mejor?", "Beto", "Cuidó cortesía y formalidad."),
    E("Si cambias de opinión para agradar al destinatario, ¿te estás adecuando o dejando de decir lo que piensas?", "Dejando de decir lo que piensas", "Adecuarse cambia la forma, no la idea.")],
   [E("Escribes un mensaje para tu abuela y otro para tu profesora, ambos para pedir ayuda con una tarea. ¿Qué es igual en los dos: el propósito o el destinatario?", "El propósito", "En ambos pides ayuda; cambian los destinatarios."),
    E("Un correo a la profesora dice «Hola, tía, necesito saber la fecha». ¿Qué conviene cambiar: el saludo o el propósito?", "El saludo", "El propósito (pedir la fecha) se mantiene.")]),
  [E("Tu curso debe invitar a una vecina del barrio a contar su oficio. Escribes: «Estimada vecina, la invitamos a nuestra sala». ¿A quién va dirigido el mensaje?", "A la vecina", "Es el destinatario.")],
  [E("En Lenguaje: ¿Qué es el propósito?", "Lo que se quiere lograr al comunicar", "Orienta el mensaje."),
   E("¿El contexto incluye el lugar y la relación entre las personas?", "Sí", "Ambos influyen en cómo hablar."),
   E("¿Qué cambia al adecuarse al destinatario: la forma o la idea?", "La forma", "La idea se mantiene.")],
  ("Imagina tres situaciones: 1) pedir a la profesora jefe una prórroga para un trabajo; 2) contarle a un amigo cómo te fue en un partido; 3) explicar a niños de 1.º qué es un volcán. Para cada una escribe: destinatario, propósito, tono y una frase de inicio.",
   "1) Destinatario: profesora jefe; propósito: pedir; tono: formal; frase: «Buenos días, profesora, quisiera pedirle una prórroga». 2) Amigo; contar; relajado; «¡Oye, no sabes cómo me fue!». 3) Niños de 1.º; explicar; simple; «Un volcán es como una montaña con un hueco por donde sale fuego».",
   ["identifica destinatario y propósito", "elige un tono adecuado", "escribe una frase coherente"], ["tabla de tres situaciones"], ["usar el mismo tono en todo", "frase sin relación con el propósito"], "Lee las frases a otra persona y pídele que adivine quién es el destinatario."),
  "Observa a alguien de tu casa hablar con dos personas distintas y anota cómo cambia su forma de hablar.",
  "Escribe el mismo mensaje para tres destinatarios distintos.")

L(OA23, 3,
  MAT_O,
  "Aprenderé a distinguir los registros formal e informal, a usar el registro adecuado a la situación y a valorar las variedades del habla sin discriminar.",
  ["Reconozco destinatario y propósito.", "Sé que hablamos distinto según la situación."],
  ["El registro es la manera de hablar o escribir según la situación. El registro formal se usa en contextos como una entrevista, una exposición o una carta al director: emplea vocabulario preciso, oraciones completas y tratamiento de respeto («usted»). El registro informal o coloquial se usa con familia y amigos: es más cercano, con expresiones del habla diaria y frases cortas.",
   "Ninguno es mejor en sí mismo: lo adecuado depende de la situación. Un error sería hablar a la alcaldesa con la misma confianza con que hablas con un amigo, o usar un tono muy rígido en una conversación cercana. Además, hay variedades del habla: formas de hablar que cambian por lugar, edad o grupo. Una persona que habla distinto no habla «mal»; habla otra variedad.",
   "Por eso la regla es doble. Primero, adecuar tu registro al contexto. Segundo, no discriminar ni burlarte de la forma de hablar de otra persona. Tu propósito es que se entienda el mensaje y que todos se sientan respetados. Si dudas, usa un registro formal pero amable: es seguro en la mayoría de las situaciones."],
  [("registro", "manera de hablar o escribir según la situación"), ("registro formal", "el que se usa en situaciones de respeto, con vocabulario preciso"), ("registro coloquial", "el de la conversación cotidiana y cercana"), ("variedad del habla", "forma de hablar propia de un lugar, edad o grupo")],
  [("Clasificar el registro", "¿«¿Me podría indicar dónde queda la biblioteca?» es formal o coloquial?",
    ["Veo el tratamiento: «podría», «indicar».", "Es cortés y preciso.", "Es formal."],
    "Formal"),
   ("Transformar", "Pasa a registro formal: «¿Me pasai el lápiz?».",
    ["Es una frase coloquial.", "Cambio a un tratamiento de respeto.", "«¿Me podría prestar el lápiz?»."],
    "¿Me podría prestar el lápiz?")],
  [("Burlarse de cómo habla otra persona.", "Se piensa que hay una sola forma correcta.", "Valora las variedades del habla."),
   ("Usar el mismo registro en todas las situaciones.", "Se habla sin pensar en el contexto.", "Adecúa el registro a quién y dónde.")],
  ([E("¿«¿Me podría prestar el lápiz?» es formal o coloquial?", "Formal", "Es cortés y preciso."),
    E("¿«¿Cachai que llegué tarde?» es formal o coloquial?", "Coloquial", "Es una expresión cotidiana."),
    E("¿Una persona que habla distinto a ti habla «mal» o habla otra variedad?", "Habla otra variedad", "No hay una sola forma correcta.")],
   [E("Una entrevista a la alcaldesa. ¿Qué registro conviene: formal o coloquial?", "Formal", "La situación lo pide."),
    E("Un mensaje a tu mejor amigo. ¿Qué registro conviene: formal o coloquial?", "Coloquial", "Es una relación cercana."),
    E("¿Qué tratamiento de respeto se usa en el registro formal: «tú» o «usted»?", "Usted", "Marca distancia respetuosa.")],
   [E("Elige la frase formal: «Disculpe, ¿podría explicarme el trabajo?» o «Oye, explícame el trabajo».", "Disculpe, ¿podría explicarme el trabajo?", "Es una frase cortés y formal."),
    E("Un compañero de otra región usa palabras que no conoces. ¿Qué haces: preguntar su significado con respeto o reírte?", "Preguntar su significado con respeto", "Valora su variedad."),
    E("En una exposición ante el curso, ¿qué registro usas: formal o muy coloquial?", "Formal", "Es una situación de presentación.")],
   [E("Ana se burla del modo de hablar de su compañera. Beto le pregunta qué significa una palabra nueva. ¿Quién respeta las variedades del habla?", "Beto", "Pregunta con interés."),
    E("Un estudiante habla con confianza excesiva a un invitado adulto. ¿El problema es de registro o de contenido?", "De registro", "No adecuó la forma a la situación.")],
   [E("¿«Estimado director:» es un saludo formal o coloquial?", "Formal", "Usa un tratamiento de respeto."),
    E("Si dudas del registro, ¿qué es más seguro: formal pero amable o muy coloquial?", "Formal pero amable", "Sirve en la mayoría de las situaciones.")]),
  [E("Un invitado de otro país visita tu curso y habla con expresiones que no conoces. ¿Cuál es una actitud respetuosa: preguntarle qué significan o corregir su forma de hablar?", "Preguntarle qué significan", "Valora su variedad.")],
  [E("¿Qué es el registro?", "La manera de hablar según la situación", "Cambia con el contexto."),
   E("¿Qué se usa en el registro formal: «usted» o apodos?", "Usted", "Es tratamiento de respeto."),
   E("¿Se debe burlar de cómo habla otra persona?", "No", "Todas las variedades merecen respeto.")],
  ("Transforma estas tres frases al registro formal: 1) «¿Me pasai el cuaderno?» 2) «Oye, ¿cachai dónde queda el baño?» 3) «Na que ver con lo que dijiste». Luego escribe una frase que invite a respetar la forma de hablar de otras personas.",
   "1) ¿Me podría pasar el cuaderno? 2) Disculpe, ¿podría indicarme dónde queda el baño? 3) No estoy de acuerdo con lo que usted dijo. Frase: «Cada persona habla de una manera distinta y todas merecen respeto».",
   ["transforma sin perder el sentido", "usa tratamiento de respeto", "propone una frase de respeto"], ["tres frases formales", "una frase de respeto"], ["cambiar el sentido", "no usar usted"], "Lee las frases a otra persona y pregunta si suenan cordiales."),
  "Escribe dos frases de saludo: una formal y una coloquial.",
  "Escribe un diálogo de cuatro líneas en que una persona cambia de registro según con quién habla.")

L(OA23, 4,
  MAT_O,
  "Aprenderé a expresar desacuerdo oralmente cuidando la relación con la otra persona: atenuadores, tono, mirada, pausas y preguntas.",
  ["Distingo registros.", "Sé reformular lo que dice el otro."],
  ["Al discrepar en forma oral, no solo importan las palabras: también el tono, la mirada, el volumen y la postura. Una frase respetuosa dicha con voz agresiva suena agresiva. Para cuidar la relación, usa recursos verbales y paraverbales. Los verbales incluyen atenuadores como «quizás», «tal vez», «me parece que» y reconocimientos como «entiendo tu punto». Los paraverbales son tono calmo, volumen moderado y pausas.",
   "Un esquema oral es: escuchar sin interrumpir, reconocer lo que el otro dijo, expresar tu desacuerdo con un atenuador, dar una razón y preguntar. Por ejemplo: «Entiendo que prefieras el viernes. Me parece que el jueves conviene más, porque hay menos tareas. ¿Qué piensas?». El atenuador «me parece que» suaviza sin esconder tu postura.",
   "Evita el sarcasmo, los gestos de burla y las generalizaciones («siempre te equivocas»). Si te sientes molesto, respira, baja el volumen y pide una pausa. Con una persona mayor, además, usa tratamiento de respeto. Discrepar bien enseña a la otra persona que puede hablar contigo aunque piensen distinto."],
  [("atenuador", "palabra que suaviza lo que se dice, como «quizás» o «me parece que»"), ("recurso paraverbal", "rasgo de la voz como el tono, el volumen o la pausa"), ("sarcasmo", "burla que dice lo contrario de lo que se piensa"), ("pausa", "momento de silencio breve al hablar")],
  [("Usar un atenuador", "Convierte «Estás equivocado» en una frase que cuide la relación.",
    ["«Estás equivocado» suena tajante.", "Agrego un atenuador y una razón.", "«Me parece que no es así, porque la fecha cambió»."],
    "Me parece que no es así, porque la fecha cambió"),
   ("Tono y mensaje", "Una persona dice «Entiendo tu punto» gritando. ¿Cuida la relación?",
    ["Las palabras son respetuosas.", "El tono es agresivo.", "No cuida la relación."],
    "No")],
  [("Cuidar solo las palabras y no el tono.", "Se grita aunque la frase sea cortés.", "Cuida la voz, la mirada y la pausa."),
   ("Usar sarcasmo como forma de discrepar.", "Se cree que es humor.", "Habla con claridad y respeto.")],
  ([E("¿«Quizás» es un atenuador o una generalización?", "Un atenuador", "Suaviza lo que se dice."),
    E("¿El tono de voz es un recurso verbal o paraverbal?", "Paraverbal", "Es rasgo de la voz."),
    E("¿Cuál cuida más la relación: «Me parece que no es así» o «Estás equivocado»?", "Me parece que no es así", "Es menos tajante.")],
   [E("¿Cuántos atenuadores hay en «Quizás, tal vez, me parece que el viernes es mejor»?", "3", "Son quizás, tal vez y me parece que."),
    E("¿Qué volumen conviene al discrepar: moderado o muy alto?", "Moderado", "Evita sonar agresivo."),
    E("¿El sarcasmo ayuda a discrepar con respeto?", "No", "Hiere a la otra persona.")],
   [E("Ordena: reconocer, preguntar, discrepar con atenuador. ¿Qué va primero en el esquema de la clase?", "Reconocer", "Se parte valorando lo dicho."),
    E("Tu amigo dice «Siempre llegas tarde». ¿Cuál respuesta evita la generalización: «No es verdad» o «Esta vez llegué tarde por el bus»?", "Esta vez llegué tarde por el bus", "Habla del caso concreto."),
    E("Si te sientes molesto, ¿qué conviene hacer: respirar y bajar el volumen o hablar más fuerte?", "Respirar y bajar el volumen", "Ayuda a mantener la calma.")],
   [E("Ana discrepa con tono calmo y mirando a la persona. Beto discrepa con ironía y mirando el techo. ¿Quién cuida la relación?", "Ana", "Mantiene tono y contacto."),
    E("Alguien dice «Claro, genial idea» con tono de burla. ¿Qué recurso usó: sarcasmo o atenuador?", "Sarcasmo", "Dice lo contrario de lo que piensa.")],
   [E("En «Entiendo su punto; me parece que podría ser distinto. ¿Qué piensa usted?», ¿qué expresión es el atenuador?", "me parece que", "Suaviza la discrepancia."),
    E("En «Entiendo que prefieras el viernes. Me parece que el jueves conviene más. ¿Qué piensas?», ¿qué paso del esquema de la clase falta?", "Dar una razón", "No explica por qué conviene el jueves.")]),
  [E("Tu equipo debe elegir un color para la pancarta y tú prefieres otro. ¿Qué dices: «Me parece que el azul se vería mejor, porque se lee más. ¿Qué opinas?» o «Ese color es horrible»?", "Me parece que el azul se vería mejor, porque se lee más. ¿Qué opinas?", "Usa atenuador, razón y pregunta.")],
  [E("¿Qué es un atenuador?", "Una palabra que suaviza lo que se dice", "Cuida la relación."),
   E("¿Qué recursos paraverbales se mencionan?", "Tono, volumen y pausa", "Son rasgos de la voz."),
   E("¿Qué conviene evitar al discrepar?", "El sarcasmo", "Daña la relación.")],
  ("Alguien dice: «Hay que hacer la actividad el lunes». Tú prefieres el jueves, porque el lunes hay prueba. Escribe cómo lo dirías con: reconocer, atenuador, razón y pregunta. Luego anota qué tono, volumen y mirada usarías.",
   "«Entiendo que el lunes te acomode. Me parece que el jueves sería mejor, porque el lunes hay prueba. ¿Qué piensas?». Tono calmo, volumen moderado, mirada a la persona y una pausa antes de preguntar.",
   ["reconoce lo dicho", "usa un atenuador", "da una razón", "indica recursos paraverbales"], ["frase de cuatro partes", "descripción de la voz"], ["tono tajante", "no dar razón"], "Dila en voz alta a otra persona y pídele que describa tu tono."),
  "Practica con alguien de tu casa dos frases de desacuerdo con distinto tono y comparen.",
  "Escribe una lista de cinco atenuadores que puedas usar en la semana.")

L(OA23, 5,
  MAT_O,
  "Aprenderé a regular el volumen, la velocidad y la dicción de mi voz según el propósito y la situación en que hablo.",
  ["Reconozco recursos paraverbales.", "Evito las muletillas."],
  ["La voz es una herramienta. El volumen es la fuerza con que hablas: debe permitir que la última persona de la sala te oiga sin que sientas que gritas. La velocidad es el ritmo: si hablas muy rápido, la audiencia se pierde; si lo haces muy lento, se aburre. La dicción es la claridad con que pronuncias cada sílaba y cada final de palabra.",
   "Estos tres recursos se ajustan al propósito. Si das un dato importante (un código, un horario, un número), disminuye la velocidad y haz una pausa. Si cuentas una escena de acción, puedes aumentar el ritmo. Si hablas ante una audiencia grande o en un lugar con ruido, sube el volumen. Si das una noticia triste, baja el volumen y la velocidad.",
   "Para mejorar la dicción, abre bien la boca, pronuncia las terminaciones (-ado, -ción, las eses finales) y evita «comerte» sílabas. Un ejercicio útil es leer en voz alta un texto lento y luego a ritmo normal. Otro consiste en grabarte y escuchar. Respira antes de comenzar y entre las ideas: sin aire, la voz pierde fuerza."],
  [("volumen", "fuerza con la que se emite la voz"), ("velocidad", "ritmo al que se habla"), ("dicción", "claridad al pronunciar los sonidos y las palabras"), ("énfasis", "mayor fuerza dada a una palabra para destacarla")],
  [("Ajustar la velocidad", "Un aviso dice: «El código de entrada es 4-5-7-1». ¿Cómo lees el código: rápido o lento con pausas?",
    ["Es un dato que el oyente debe anotar.", "Debe poder seguirlo.", "Lo leo lento, con pausas entre cifras."],
    "Lento, con pausas"),
   ("Cuidar la dicción", "¿Cuál se pronuncia con mejor dicción: «hablado» con la d final de -ado o «hablao»?",
    ["Reviso la terminación.", "«-ado» se pronuncia completa en lo formal.", "Elijo «hablado»."],
    "«hablado»")],
  [("Hablar fuerte creyendo que es gritar.", "Se confunde volumen y grito.", "Habla de modo que llegue al fondo sin tensión."),
   ("Hablar rápido para terminar pronto.", "El oyente pierde la información.", "Baja la velocidad en los datos clave.")],
  ([E("¿El volumen es la fuerza de la voz o su ritmo?", "La fuerza de la voz", "Lo que se regula es qué tan fuerte se habla."),
    E("¿La velocidad es el ritmo o la claridad?", "El ritmo", "Se refiere a qué tan rápido se habla."),
    E("¿La dicción es la claridad al pronunciar o el tono de la voz?", "La claridad al pronunciar", "Incluye sílabas y finales.")],
   [E("En un aviso con un horario importante, ¿bajas o subes la velocidad?", "Bajas la velocidad", "El oyente debe poder anotar."),
    E("En una sala con mucho ruido, ¿subes o bajas el volumen?", "Subes el volumen", "Para que te oigan."),
    E("En una noticia triste, ¿qué volumen y ritmo convienen: bajos o muy altos?", "Bajos", "Transmiten seriedad y respeto.")],
   [E("El código 4-5-7-1 se lee con una pausa entre cifras. ¿Cuántas pausas haces?", "3", "Hay tres espacios entre cuatro cifras."),
    E("Lees una escena de persecución. ¿Qué ritmo puede ayudar: rápido o muy lento?", "Rápido", "Un ritmo rápido transmite acción."),
    E("En «comprado», ¿qué letra suele perderse al hablar rápido y afecta la dicción: la d o la p?", "La d", "Se debilita en el habla rápida.")],
   [E("Ana lee un horario a velocidad de carrera. Beto lo lee despacio, con pausas, y lo repite. ¿Quién ajustó mejor la velocidad?", "Beto", "Dio tiempo para anotar."),
    E("Una persona habla en voz baja en un salón grande. ¿Qué necesita ajustar: el volumen o la dicción?", "El volumen", "No llega al fondo.")],
   [arith("Lees un código de 8 cifras y haces una pausa de 1 segundo cada 2 cifras. ¿Cuántas pausas haces entre grupos?", "8//2-1", "Hay 4 grupos y 3 pausas entre ellos."),
    E("Respirar antes de comenzar, ¿ayuda o dificulta la fuerza de la voz?", "Ayuda", "Da aire para sostener la voz.")]),
  [E("Debes avisar al curso: «La salida es el jueves a las 8:30». ¿Qué palabras destacas con énfasis: «jueves» y «8:30» o «la» y «es»?", "jueves y 8:30", "Son los datos clave.")],
  [E("¿Qué recurso regula qué tan fuerte hablas?", "El volumen", "Es la fuerza de la voz."),
   E("¿Qué se hace con los datos importantes: se leen lento o rápido?", "Lento", "Para que se anoten."),
   E("¿Qué mejora la dicción: abrir bien la boca o hablar con la boca cerrada?", "Abrir bien la boca", "Aclara los sonidos.")],
  ("Lee en voz alta este aviso dos veces y marca cómo lo hiciste cada vez: «Atención, estudiantes. El jueves a las 8:30, el curso se reunirá en el patio con su cuaderno y un lápiz. La actividad durará dos horas». La primera vez a ritmo normal; la segunda con énfasis y pausas en jueves, 8:30, patio y dos horas. Anota qué cambió en volumen, velocidad y dicción.",
   "Primera lectura: volumen medio, velocidad uniforme. Segunda: pausas antes de los datos, mayor énfasis en jueves y 8:30, dicción clara en «reunirá» y «durará». Se entendió mejor en la segunda.",
   ["marca los datos clave", "ajusta velocidad con pausas", "explica los cambios"], ["lectura en voz alta", "nota de comparación"], ["leer todo igual", "gritar"], "Pide a otra persona que anote los datos que oyó y compara."),
  "Lee un trozo de un libro con tres volúmenes distintos y elige el mejor para tu sala.",
  "Escribe un aviso de tres datos y marca dónde bajarías la velocidad.")

L(OA23, 6,
  MAT_O,
  "Aprenderé a revisar el efecto que mi forma de hablar produjo en la audiencia usando una pequeña encuesta y a decidir qué mejorar.",
  ["Regulo volumen, velocidad y dicción.", "Uso un registro adecuado."],
  ["Hablar bien no es solo hacerlo con cuidado: es comprobar qué efecto tuvo en quienes escuchan. Para evaluarlo, puedes pedir a la audiencia que responda preguntas breves: ¿oyó bien?, ¿entendió la idea principal?, ¿recuerda un ejemplo?, ¿el tono fue adecuado? Las respuestas se anotan en una tabla y se transforman en porcentajes.",
   "Un porcentaje se calcula dividiendo la parte entre el total y multiplicando por 100. Por ejemplo, si 18 de 24 personas entendieron la idea principal, el porcentaje es 18 × 100 ÷ 24 = 75. Comparar los porcentajes muestra qué aspecto funcionó mejor y cuál necesita más trabajo. El más bajo es tu prioridad de mejora.",
   "No te quedes solo con los números. Pide un comentario concreto: «¿Qué parte te costó más oír?». Combina los datos con lo que tú sentiste al hablar. Luego elige una mejora específica para el próximo ensayo, como «bajar la velocidad al dar fechas». Anótala y compruébala la próxima vez: así tu forma de hablar mejora con evidencia."],
  [("efecto", "resultado que produce algo en quien lo recibe"), ("porcentaje", "parte de un total expresada sobre 100"), ("prioridad de mejora", "aspecto que conviene mejorar primero"), ("encuesta", "serie de preguntas breves para recoger opiniones")],
  [("Calcular un porcentaje", "De 24 personas, 18 entendieron la idea principal (dato de ejemplo). ¿Qué porcentaje es?",
    ["Divido 18 entre 24.", "Multiplico por 100: 18 × 100 ÷ 24.", "El resultado es 75."],
    "75 %"),
   ("Elegir la prioridad", "Resultados de ejemplo: oyó bien 90 %; entendió 75 %; recuerda el ejemplo 40 %. ¿Qué mejoras primero?",
    ["Comparo los tres porcentajes.", "El más bajo es 40 %.", "La prioridad es el ejemplo."],
    "Que recuerden el ejemplo")],
  [("Evaluar solo con la impresión propia.", "Se cree que uno sabe cómo sonó.", "Pide a la audiencia que responda preguntas breves."),
   ("Mejorar todo a la vez.", "Se dispersa el esfuerzo.", "Escoge una mejora concreta por ensayo.")],
  ([E("¿Para qué sirve una encuesta breve a la audiencia?", "Para saber qué efecto tuvo la presentación", "Da evidencia de lo ocurrido."),
    E("¿Qué aspecto se mejora primero: el de mayor porcentaje o el de menor?", "El de menor porcentaje", "Es el que más necesita trabajo."),
    E("Si 24 de 24 personas oyeron bien, ¿qué porcentaje es?", "100 %", "Es todo el grupo.")],
   [arith("De 20 personas, 15 entendieron la idea principal (dato de ejemplo). ¿Qué porcentaje es?", "15*100//20", "Se divide la parte entre el total y se multiplica por 100.", " %"),
    E("Resultados de ejemplo: oyó bien 85 %; recuerda ejemplo 55 %; tono adecuado 90 %. ¿Cuál es la prioridad de mejora?", "Recordar el ejemplo", "Es el más bajo."),
    E("¿Un comentario concreto como «me costó oír el final» es más útil que «estuvo bien»?", "Sí", "Dice qué mejorar.")],
   [arith("De 25 personas, 20 oyeron bien (dato de ejemplo). ¿Qué porcentaje oyó bien?", "20*100//25", "Se divide por el total y se multiplica por 100.", " %"),
    arith("Si 18 de 24 entendieron y 9 de 24 recuerdan el ejemplo (datos de ejemplo), ¿cuántas personas más entendieron que recuerdan?", "18-9", "Se resta una cantidad de la otra."),
    E("Una mejora concreta es «bajar la velocidad al dar fechas». ¿Es concreta o vaga?", "Concreta", "Indica qué hacer y cuándo.")],
   [E("Ana dice «sentí que me fue bien». Beto reparte una encuesta de tres preguntas. ¿Quién tiene evidencia del efecto?", "Beto", "Recogió respuestas de la audiencia."),
    E("Resultados de ejemplo: 90 %, 75 % y 40 %. Si mejoras solo el 40 %, ¿atiendes la prioridad?", "Sí", "Es el aspecto más débil.")],
   [arith("Antes de la mejora, 9 de 24 recordaban el ejemplo (dato de ejemplo). Después, 18 de 24. ¿Cuántas personas más lo recordaron?", "18-9", "Se resta la cantidad inicial de la final."),
    E("Si el porcentaje de recuerdo subió, ¿la mejora funcionó o no?", "Funcionó", "Aumentó el efecto buscado.")]),
  [arith("Una presentación de ejemplo tuvo 30 asistentes. 24 oyeron bien. ¿Qué porcentaje oyó bien?", "24*100//30", "Se divide por el total y se multiplica por 100.", " %")],
  [E("¿Qué se calcula dividiendo la parte entre el total y multiplicando por 100?", "El porcentaje", "Es la fórmula del porcentaje."),
   E("¿Qué debes hacer con el aspecto de menor porcentaje?", "Mejorarlo primero", "Es la prioridad."),
   E("¿Conviene pedir comentarios concretos además de números?", "Sí", "Dan información sobre qué cambiar.")],
  ("Prepara una encuesta de tres preguntas para una audiencia de 5 personas y aplícala tras leer en voz alta un texto de una página: 1) ¿Oyó bien? 2) ¿Entendió la idea principal? 3) ¿Recuerda un ejemplo? Calcula cuántas respondieron sí a cada una y elige una mejora concreta.",
   "Oyeron bien 5 de 5 (100 %); entendieron 4 de 5 (80 %); recuerdan un ejemplo 2 de 5 (40 %). Mejora: repetir el ejemplo al final y hacer una pausa antes de él.",
   ["formula tres preguntas", "calcula respuestas", "elige una mejora concreta"], ["encuesta", "resultados", "mejora"], ["quedarse con la impresión propia", "mejoras vagas"], "Repite la lectura con la mejora y vuelve a aplicar la encuesta."),
  "Pide a una persona de tu casa que te diga qué parte de tu última explicación le costó más.",
  "Diseña una encuesta de cuatro preguntas sobre el efecto de una exposición.")
